BEGIN;

-- Settings live only until COMMIT, so the passwords never outlast it.
SELECT
    set_config('ds_grants.app', :'app', true),
    set_config('ds_grants.read_shared', :'read_shared', true),
    set_config('ds_grants.schema_gate', :'schema_gate', true),
    set_config('ds_grants.api', :'api', true),
    set_config('ds_grants.api_password', :'api_password', true),
    set_config('ds_grants.api_connection_limit', :'api_connection_limit', true),
    set_config('ds_grants.aggregator', :'aggregator', true),
    set_config('ds_grants.aggregator_password', :'aggregator_password', true),
    set_config('ds_grants.aggregator_connection_limit', :'aggregator_connection_limit', true),
    set_config('ds_grants.enricher', :'enricher', true),
    set_config('ds_grants.enricher_password', :'enricher_password', true),
    set_config('ds_grants.enricher_connection_limit', :'enricher_connection_limit', true),
