\gset ignored_

-- 1. Roles.
DO $roles$
DECLARE
    app text := current_setting('ds_grants.app');
    r record;
    seen text[] := ARRAY[]::text[];
BEGIN
    IF NOT (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) THEN
        RAISE EXCEPTION 'postgres-grants.sql must run as a superuser, not %',
            current_user;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = app) THEN
        RAISE EXCEPTION 'the app role % does not exist: run postgres-roles.sql first',
            app;
    END IF;
    FOR r IN
        SELECT v.kind, current_setting('ds_grants.' || v.kind) AS name
        FROM (VALUES
        ('read_shared'),
        ('schema_gate')) AS v(kind)
    LOOP
        IF r.name = app OR r.name = current_user OR r.name = ANY (seen) THEN
            RAISE EXCEPTION 'the % group name % must be a new, separate role',
                r.kind, r.name;
        END IF;
        seen := seen || r.name;
        IF EXISTS (SELECT 1 FROM pg_roles
                   WHERE rolname = r.name AND (rolsuper OR rolcanlogin)) THEN
            RAISE EXCEPTION 'refusing to turn % into a group (a superuser or a login role)',
                r.name;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.name) THEN
            EXECUTE format('CREATE ROLE %I', r.name);
        END IF;
        EXECUTE format('ALTER ROLE %I WITH NOLOGIN NOSUPERUSER NOCREATEDB '
                       'NOCREATEROLE NOREPLICATION NOBYPASSRLS', r.name);
    END LOOP;
    FOR r IN
        SELECT v.kind, current_setting('ds_grants.' || v.kind) AS name,
               current_setting('ds_grants.' || v.kind || '_password') AS password,
               current_setting('ds_grants.' || v.kind || '_connection_limit')
                   AS connection_limit
        FROM (VALUES
        ('api', 'observed'),
        ('aggregator', 'observed'),
        ('enricher', 'observed'),
        ('notifier', 'observed'),
        ('writer', 'observed'),
        ('schedule_reference', 'narrow'),
        ('stations', 'narrow'),
        ('incidents', 'narrow'),
        ('schedule_ingest', 'narrow')) AS v(kind, status)
    LOOP
        IF r.name = app OR r.name = current_user OR r.name = ANY (seen) THEN
            RAISE EXCEPTION 'the % role name % must be a new, separate role',
                r.kind, r.name;
        END IF;
        seen := seen || r.name;
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.name AND rolsuper) THEN
            RAISE EXCEPTION 'refusing to demote existing superuser % (the % role)',
                r.name, r.kind;
        END IF;
        IF r.connection_limit !~ '^(-1|[0-9]+)$' THEN
            RAISE EXCEPTION 'the % role connection limit % is not a whole number',
                r.kind, r.connection_limit;
        END IF;
        IF r.password = '' THEN
            RAISE EXCEPTION 'no password for the % role: set DS_PG_%_PASSWORD',
                r.kind, upper(r.kind);
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.name) THEN
            EXECUTE format('CREATE ROLE %I', r.name);
        END IF;
        EXECUTE format('ALTER ROLE %I WITH LOGIN NOSUPERUSER NOCREATEDB '
                       'NOCREATEROLE NOREPLICATION NOBYPASSRLS INHERIT '
                       'CONNECTION LIMIT %s', r.name, r.connection_limit);
        EXECUTE format('ALTER ROLE %I PASSWORD %L', r.name, r.password);
    END LOOP;
END
$roles$;

-- 2. Memberships, 3. CONNECT and USAGE.
DO $members$
DECLARE
    app text := current_setting('ds_grants.app');
    app_oid oid := (SELECT oid FROM pg_roles WHERE rolname = app);
    r record;
    member_oid oid;
BEGIN
    FOR r IN
        SELECT v.kind, v.status, current_setting('ds_grants.' || v.kind) AS name
        FROM (VALUES
        ('api', 'observed'),
        ('aggregator', 'observed'),
        ('enricher', 'observed'),
        ('notifier', 'observed'),
        ('writer', 'observed'),
        ('schedule_reference', 'narrow'),
        ('stations', 'narrow'),
        ('incidents', 'narrow'),
        ('schedule_ingest', 'narrow')) AS v(kind, status)
    LOOP
        member_oid := (SELECT oid FROM pg_roles WHERE rolname = r.name);
        IF r.status = 'observed' AND NOT EXISTS (
            SELECT 1 FROM pg_auth_members
            WHERE roleid = app_oid AND member = member_oid) THEN
            EXECUTE format('GRANT %I TO %I', app, r.name);
        ELSIF r.status = 'narrow' AND EXISTS (
            SELECT 1 FROM pg_auth_members
            WHERE roleid = app_oid AND member = member_oid) THEN
            EXECUTE format('REVOKE %I FROM %I', app, r.name);
        END IF;
        EXECUTE format('GRANT CONNECT ON DATABASE %I TO %I',
                       current_database(), r.name);
        EXECUTE format('GRANT USAGE ON SCHEMA public TO %I', r.name);
    END LOOP;
    FOR r IN
        SELECT current_setting('ds_grants.' || v.kind) AS member,
               current_setting('ds_grants.' || v.grp) AS grp
        FROM (VALUES
        ('api', 'read_shared'),
        ('api', 'schema_gate'),
        ('aggregator', 'read_shared'),
        ('aggregator', 'schema_gate'),
        ('enricher', 'schema_gate'),
        ('notifier', 'read_shared'),
        ('notifier', 'schema_gate'),
        ('writer', 'read_shared'),
        ('writer', 'schema_gate'),
        ('schedule_reference', 'schema_gate'),
        ('stations', 'schema_gate'),
        ('incidents', 'schema_gate'),
        ('schedule_ingest', 'schema_gate')) AS v(kind, grp)
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM pg_auth_members
            WHERE roleid = (SELECT oid FROM pg_roles WHERE rolname = r.grp)
              AND member = (SELECT oid FROM pg_roles WHERE rolname = r.member)) THEN
            EXECUTE format('GRANT %I TO %I', r.grp, r.member);
        END IF;
    END LOOP;
END
$members$;

-- 4. Grants. Everything the groups and the created roles hold in schema
-- public is revoked first, so a grant removed from db-grants.yaml goes
-- away on the next run. Observed roles end with nothing of their own: they
-- use the app role's privileges.
DO $grants$
DECLARE
    r record;
    grantee text;
BEGIN
    FOR grantee IN
        SELECT current_setting('ds_grants.' || v.kind)
        FROM (VALUES
        ('read_shared'),
        ('schema_gate'),
        ('api'),
        ('aggregator'),
        ('enricher'),
        ('notifier'),
        ('writer'),
        ('schedule_reference'),
        ('stations'),
        ('incidents'),
        ('schedule_ingest')) AS v(kind)
    LOOP
        EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', grantee);
        EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', grantee);
        EXECUTE format('REVOKE ALL ON ALL ROUTINES IN SCHEMA public FROM %I', grantee);
    END LOOP;

    IF to_regclass('public._sqlx_migrations') IS NOT NULL THEN
        EXECUTE format('GRANT SELECT ON public._sqlx_migrations TO %I',
                       current_setting('ds_grants.schema_gate'));
    END IF;
    FOR r IN
        SELECT v.tbl
        FROM (VALUES
        ('trains'),
        ('train_subscriptions'),
        ('train_movement_events'),
        ('train_current_state'),
        ('trust_event_backlog'),
        ('train_reasons'),
        ('notifier_forward_queue'),
        ('station_samples'),
        ('station_full_coverage_samples'),
        ('full_coverage_line_stats'),
        ('full_coverage_line_window_stats'),
        ('island_of_ireland_lines'),
        ('island_of_ireland_stations'),
        ('island_of_ireland_station_samples'),
        ('line_status'),
        ('line_status_history'),
        ('incidents'),
        ('incident_history'),
        ('incident_feed_state'),
        ('ingest_freshness'),
        ('line_status_daily_stats'),
        ('line_status_half_hourly_stats'),
        ('line_status_daily_coverage_stats'),
        ('line_status_half_hourly_coverage_stats'),
        ('full_coverage_window_verdicts'),
        ('corpus_crosswalk_build'),
        ('corpus_stanox_crs'),
        ('corpus_tiploc_crs'),
        ('stations'),
        ('tocs'),
        ('stanox_crs'),
        ('tiploc_crs'),
        ('fixed_links'),
        ('corpus_locations'),
        ('corpus_deliveries'),
        ('schedule_calling_points_full'),
        ('schedule_destination_departures'),
        ('schedule_network_departures'),
        ('schedule_line_population'),
        ('line_train_summaries'),
        ('schedule_services'),
        ('tiploc_locations'),
        ('schedule_reference_publishes'),
        ('schedule_feed_ingests')) AS v(tbl)
        WHERE to_regclass(format('public.%I', v.tbl)) IS NOT NULL
    LOOP
        EXECUTE format('GRANT SELECT ON public.%I TO %I', r.tbl,
                       current_setting('ds_grants.read_shared'));
    END LOOP;

    -- Narrow roles: exactly their grants.
    FOR r IN
        SELECT v.tbl, current_setting('ds_grants.' || v.kind) AS grantee,
               v.priv, v.cols
        FROM (VALUES
        ('schedule_calling_points_full_publish_keys', 'schedule_reference', 'SELECT', ''),
        ('schedule_calling_points_full_publish_keys', 'schedule_reference', 'INSERT', ''),
        ('schedule_calling_points_full_publish_keys', 'schedule_reference', 'DELETE', ''),
        ('schedule_destination_departures_publish_keys', 'schedule_reference', 'SELECT', ''),
        ('schedule_destination_departures_publish_keys', 'schedule_reference', 'INSERT', ''),
        ('schedule_destination_departures_publish_keys', 'schedule_reference', 'DELETE', ''),
        ('incidents', 'incidents', 'SELECT', ''),
        ('incidents', 'incidents', 'INSERT', ''),
        ('incidents', 'incidents', 'UPDATE', ''),
        ('incident_history', 'incidents', 'SELECT', ''),
        ('incident_history', 'incidents', 'INSERT', ''),
        ('incident_feed_state', 'incidents', 'SELECT', ''),
        ('incident_feed_state', 'incidents', 'INSERT', ''),
        ('incident_feed_state', 'incidents', 'UPDATE', ''),
        ('ingest_freshness', 'stations', 'SELECT', ''),
        ('ingest_freshness', 'stations', 'INSERT', ''),
        ('ingest_freshness', 'stations', 'UPDATE', ''),
        ('ingest_freshness', 'incidents', 'SELECT', ''),
        ('ingest_freshness', 'incidents', 'INSERT', ''),
        ('ingest_freshness', 'incidents', 'UPDATE', ''),
        ('corpus_crosswalk_build', 'schedule_ingest', 'SELECT', ''),
        ('corpus_crosswalk_build', 'schedule_ingest', 'INSERT', ''),
        ('corpus_crosswalk_build', 'schedule_ingest', 'UPDATE', ''),
        ('corpus_crosswalk_build', 'schedule_ingest', 'DELETE', ''),
        ('corpus_stanox_crs', 'schedule_ingest', 'SELECT', ''),
        ('corpus_stanox_crs', 'schedule_ingest', 'INSERT', ''),
        ('corpus_stanox_crs', 'schedule_ingest', 'UPDATE', ''),
        ('corpus_stanox_crs', 'schedule_ingest', 'DELETE', ''),
        ('corpus_tiploc_crs', 'schedule_ingest', 'SELECT', ''),
        ('corpus_tiploc_crs', 'schedule_ingest', 'INSERT', ''),
        ('corpus_tiploc_crs', 'schedule_ingest', 'UPDATE', ''),
        ('corpus_tiploc_crs', 'schedule_ingest', 'DELETE', ''),
        ('corpus_tiploc_crs', 'schedule_reference', 'SELECT', ''),
        ('stations', 'stations', 'SELECT', ''),
        ('stations', 'stations', 'INSERT', ''),
        ('stations', 'stations', 'UPDATE', ''),
        ('stations', 'incidents', 'SELECT', ''),
        ('stations', 'schedule_ingest', 'SELECT', ''),
        ('stanox_crs', 'schedule_reference', 'SELECT', ''),
        ('stanox_crs', 'schedule_reference', 'INSERT', ''),
        ('stanox_crs', 'schedule_reference', 'UPDATE', ''),
        ('stanox_crs', 'schedule_reference', 'DELETE', ''),
        ('tiploc_crs', 'schedule_reference', 'SELECT', ''),
        ('tiploc_crs', 'schedule_reference', 'INSERT', ''),
        ('tiploc_crs', 'schedule_reference', 'UPDATE', ''),
        ('tiploc_crs', 'schedule_reference', 'DELETE', ''),
        ('fixed_links', 'schedule_reference', 'SELECT', ''),
        ('fixed_links', 'schedule_reference', 'INSERT', ''),
        ('fixed_links', 'schedule_reference', 'UPDATE', ''),
        ('fixed_links', 'schedule_reference', 'DELETE', ''),
        ('corpus_locations', 'schedule_ingest', 'SELECT', ''),
        ('corpus_locations', 'schedule_ingest', 'INSERT', ''),
        ('corpus_locations', 'schedule_ingest', 'UPDATE', ''),
        ('corpus_locations', 'schedule_ingest', 'DELETE', ''),
        ('corpus_deliveries', 'schedule_ingest', 'SELECT', ''),
        ('corpus_deliveries', 'schedule_ingest', 'INSERT', ''),
        ('corpus_deliveries', 'schedule_ingest', 'UPDATE', ''),
        ('corpus_deliveries', 'schedule_ingest', 'DELETE', ''),
        ('schedule_calling_points_full', 'schedule_reference', 'SELECT', ''),
        ('schedule_calling_points_full', 'schedule_reference', 'INSERT', ''),
        ('schedule_calling_points_full', 'schedule_reference', 'UPDATE', ''),
        ('schedule_calling_points_full', 'schedule_reference', 'DELETE', ''),
        ('schedule_destination_departures', 'schedule_reference', 'SELECT', ''),
        ('schedule_destination_departures', 'schedule_reference', 'INSERT', ''),
        ('schedule_destination_departures', 'schedule_reference', 'UPDATE', ''),
        ('schedule_destination_departures', 'schedule_reference', 'DELETE', ''),
        ('schedule_network_departures', 'schedule_reference', 'SELECT', ''),
        ('schedule_network_departures', 'schedule_reference', 'INSERT', ''),
        ('schedule_network_departures', 'schedule_reference', 'UPDATE', ''),
        ('schedule_network_departures', 'schedule_reference', 'DELETE', ''),
        ('schedule_line_population', 'schedule_reference', 'SELECT', ''),
        ('schedule_line_population', 'schedule_reference', 'INSERT', ''),
        ('schedule_line_population', 'schedule_reference', 'UPDATE', ''),
        ('schedule_line_population', 'schedule_reference', 'DELETE', ''),
        ('line_train_summaries', 'schedule_reference', 'SELECT', ''),
        ('line_train_summaries', 'schedule_reference', 'INSERT', ''),
        ('line_train_summaries', 'schedule_reference', 'UPDATE', ''),
        ('line_train_summaries', 'schedule_reference', 'DELETE', ''),
        ('schedule_services', 'schedule_reference', 'SELECT', ''),
        ('schedule_services', 'schedule_reference', 'INSERT', ''),
        ('schedule_services', 'schedule_reference', 'UPDATE', ''),
        ('schedule_services', 'schedule_reference', 'DELETE', ''),
        ('tiploc_locations', 'schedule_reference', 'SELECT', ''),
        ('tiploc_locations', 'schedule_reference', 'INSERT', ''),
        ('tiploc_locations', 'schedule_reference', 'UPDATE', ''),
        ('tiploc_locations', 'schedule_reference', 'DELETE', ''),
        ('schedule_reference_publishes', 'schedule_reference', 'SELECT', ''),
        ('schedule_reference_publishes', 'schedule_reference', 'INSERT', ''),
        ('schedule_reference_publishes', 'schedule_reference', 'UPDATE', ''),
        ('schedule_feed_ingests', 'schedule_ingest', 'SELECT', ''),
        ('schedule_feed_ingests', 'schedule_ingest', 'INSERT', '')) AS v(tbl, kind, priv, cols)
        WHERE to_regclass(format('public.%I', v.tbl)) IS NOT NULL
    LOOP
        IF r.cols = '' THEN
            EXECUTE format('GRANT %s ON public.%I TO %I', r.priv, r.tbl, r.grantee);
        ELSE
            EXECUTE format('GRANT %s (%s) ON public.%I TO %I', r.priv,
                (SELECT string_agg(quote_ident(c), ', ')
                 FROM unnest(string_to_array(r.cols, ',')) AS c),
                r.tbl, r.grantee);
        END IF;
    END LOOP;
    FOR r IN
        SELECT v.seq, current_setting('ds_grants.' || v.kind) AS grantee
        FROM (VALUES
        ('incident_history_id_seq', 'incidents'),
        ('fixed_links_id_seq', 'schedule_reference'),
        ('corpus_locations_id_seq', 'schedule_ingest')) AS v(seq, kind)
        WHERE to_regclass(format('public.%I', v.seq)) IS NOT NULL
    LOOP
        EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE public.%I TO %I',
                       r.seq, r.grantee);
    END LOOP;
    FOR r IN
        SELECT v.sig, current_setting('ds_grants.' || v.kind) AS grantee
        FROM (VALUES
        ('analyze_publish_keys(text)', 'schedule_reference')) AS v(sig, kind)
        WHERE to_regprocedure('public.' || v.sig) IS NOT NULL
    LOOP
        EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I',
                       to_regprocedure('public.' || r.sig), r.grantee);
    END LOOP;
END
$grants$;

COMMIT;
